import React from 'react';
import './logIn.css';
import foobarImage from './foobar.jpg';
import { useNavigate } from 'react-router-dom';



function LogIn() {
    const navigate = useNavigate();
   

    const handleLogInClick = () => {
        
        try {
          // Fetch user data from your JSON file or backend API
          const emailInput = document.getElementById('email');
          const passwordInput = document.getElementById('password');
      
          const email = emailInput.value;
          const password = passwordInput.value;
    
          // Check if the provided credentials match any user in the database
          const validUser = users.find(user => user.email === email && user.password === password);
    
          if (validUser) {
            navigate('homePage');
          }
        } catch (error) {
          return;
        }
      };

    const handleSignupClick = () => {
      // Navigate to the signup page
      navigate('SignUp');
    };
    return (
        <header id="header">
        <div class="layer"></div>

        <div class="main">
            <div class="left">
            <img src={foobarImage} alt="" />
                <p>Connect with friends and the world around you on Foobar.</p>
            </div>
            <div class="right">
                <form action="#">
                    <div class="form_body">
                        <input type="text " placeholder="Email or phone number" required></input>
                        <input type="password" placeholder="Password" required></input>
                        <button class="login " onclick={handleLogInClick}>Log In</button>
                        <p class="forget">forgot password?</p>
                        <hr></hr>
                        <button class="create" onClick={handleSignupClick}>Create new account</button>
                    </div>
                </form>
                <p class="foot"><span>Create a Page</span> for a celebrity, brand or business.</p>
            </div>
        </div>
        </header>

);
}

export default LogIn;
